@router.get("/all-reports")
async def get_all_benchmark_reports():
    """Retrieve complete suite of evaluation, benchmark, and red-teaming reports."""
    # Ensure fertilizer ML report is populated
    if not fertilizer_ml.is_trained:
        fertilizer_ml.train_and_evaluate()
    
    reports = EVALUATION_REPORTS_CACHE.copy()
    reports["fertilizer_ml_report"] = fertilizer_ml.evaluation_results
    return reports
